async function findWarrantPerson(warrantId){
  if(!isAdmin())throw new Error('Apenas administradores podem revisar associações.');
  const input=document.querySelector('[data-warrant-search-input="'+CSS.escape(warrantId)+'"]'),name=String(input?.value||'').trim();if(name.length<3)throw new Error('Digite pelo menos três letras do nome.');
  const results=await lookupSimilarPeople(name);warrantSearchResults.set(warrantId,results||[]);await renderWarrants();
}
async function addWarrantCandidate(warrantId,personId){
  if(!isAdmin())throw new Error('Apenas administradores podem vincular registros.');
  const {data:existing,error:findError}=await state.client.from('arrest_warrant_matches').select('id,review_status').eq('warrant_id',warrantId).eq('person_id',personId).limit(1);
  if(findError)throw findError;if(existing?.some(row=>row.review_status==='confirmed'))throw new Error('Este indivíduo já está confirmado para o mandado.');
  if(existing?.length){toast('Esta sugestão já está aguardando revisão.');return}
  const {error}=await state.client.from('arrest_warrant_matches').insert({warrant_id:warrantId,person_id:personId,match_basis:'manual_review',confidence:0,review_status:'candidate'});
  if(error)throw error;toast('Indicação adicionada à fila de revisão.');await renderWarrants();
}
async function reviewWarrantMatch(button){
  if(!isAdmin())throw new Error('Apenas administradores podem revisar correspondências.');
  const decision=button.dataset.warrantDecision,verb=decision==='confirmed'?'confirmar este vínculo':'marcar como não correspondente';
  if(!window.confirm('Tem certeza que deseja '+verb+'? Confirme a identidade e o status na fonte oficial.'))return;
  const {error}=await state.client.rpc('admin_review_arrest_warrant_match',{p_match_id:button.dataset.warrantReview,p_decision:decision});
  if(error)throw error;toast(decision==='confirmed'?'Vínculo confirmado. O aviso ficará visível aos operadores.':'Correspondência rejeitada.');await renderWarrants();
}
async function openWarrantDocument(path){
  if(!['admin','operator'].includes(state.profile?.role))throw new Error('Apenas usuários autorizados podem abrir documentos.');
  const tab=window.open('about:blank','_blank');const {data,error}=await state.client.storage.from('warrant-documents').createSignedUrl(path,60);
  if(error){tab?.close();throw error}if(tab)tab.location=data.signedUrl;else window.location.href=data.signedUrl;
}
async function readWarrantPdf(){
  if(!isAdmin())throw new Error('Apenas administradores podem ler uma peça.');
  const form=$('#warrantManualForm'),file=form?.querySelector('input[name="document"]')?.files?.[0],status=$('#warrantPdfOcrStatus');if(!file)throw new Error('Selecione o PDF antes de iniciar a leitura.');
  status.textContent='Lendo o documento localmente…';const result=await processOcrFiles([file],{onProgress:progress=>{status.textContent=formatWarrantOcrProgress(progress)}});
  const suggestion=extractWarrantPersonSuggestions(result.text),fields={warrant_number:'warrant_number',full_name:'full_name',cpf_digits:'cpf',rg:'person_rg',birth_date:'birth_date',address_primary:'person_address_primary',filiation:'person_filiation',process_information:'person_process_information',process_reference:'source_reference'};
  let filled=0;for(const [key,name]of Object.entries(fields)){const input=form.elements[name],value=suggestion[key];if(input&&value&&!input.value){input.value=value;filled++}}
  status.textContent=filled?'Sugestões locais preenchidas ('+filled+' campo(s)). Confira nome, documentos e informações processuais antes de salvar.':'A leitura não encontrou campos com segurança. Confira a peça e preencha os dados manualmente.';
}
async function loadPage(){if(!state.session){authPage();return}if(state.page==='photoSearch')state.page='people';if(state.page==='team'&&!isAdmin())state.page='people';if(state.page==='history'&&!isAdmin())state.page='dashboard';if(state.page==='warrants'&&!['operator','admin'].includes(state.profile?.role))state.page='people';state.selected=null;saveLastView();nav();loadingPage();try{if(state.page==='dashboard')await renderDashboard();else if(['people','vehicles'].includes(state.page)){await loadRecords();await renderRecords()}else if(state.page==='warrants')await renderWarrants();else if(state.page==='team')await renderTeam();else if(state.page==='history')await renderHistory()}catch(e){frame('<div class="error-box">'+esc(msg(e))+'</div>')}}
async function galleryPhotos(entity,record){const photos=[];const {data,error}=await state.client.from('record_photos').select('id,photo_path,is_cover,crop_position,created_at').eq('entity',entity).eq('entity_id',record.id).order('created_at',{ascending:true});if(error)console.warn('A galeria unificada não está disponível; vou tentar as fotos antigas.',error);else photos.push(...(data||[]));const legacyTable=entity==='people'?'person_photos':'vehicle_photos',foreignKey=entity==='people'?'person_id':'vehicle_id';let legacy=[];for(const [columns,sort] of [['photo_path,created_at,sort_order',['sort_order','created_at']],['photo_path,created_at',['created_at']],['photo_path',[]]]){let query=state.client.from(legacyTable).select(columns).eq(foreignKey,record.id);for(const column of sort)query=query.order(column,{ascending:true});const result=await query;if(!result.error){legacy=result.data||[];break}}const pathKey=path=>externalPhotoUrl(path)||String(path||'');for(const old of legacy){if(!old.photo_path||photos.some(photo=>pathKey(photo.photo_path)===pathKey(old.photo_path)))continue;const isCover=!photos.some(photo=>photo.is_cover)&&(record.photo_path?pathKey(old.photo_path)===pathKey(record.photo_path):!photos.length);photos.push({id:null,photo_path:old.photo_path,is_cover:isCover,crop_position:'50% 50%',created_at:old.created_at})}if(record.photo_path&&!photos.some(photo=>pathKey(photo.photo_path)===pathKey(record.photo_path)))photos.unshift({id:null,photo_path:record.photo_path,is_cover:!photos.some(photo=>photo.is_cover),crop_position:record.photo_position||'50% 50%'});const seenPaths=new Set(),uniquePhotos=orderedPhotos(photos).filter(photo=>{const key=pathKey(photo.photo_path);if(!key||seenPaths.has(key))return false;seenPaths.add(key);return true});const urls=await galleryPhotoUrls(uniquePhotos.map(photo=>photo.photo_path));return uniquePhotos.map(photo=>({...photo,url:urls.get(String(photo.photo_path))||''}))}
function parsePhotoCrop(value,portrait=false){const parts=String(value||'').match(/^(\d{1,3}(?:\.\d+)?)%\s+(\d{1,3}(?:\.\d+)?)%(?:\|z=([\d.]+))?$/);if(!parts)return{position:portrait?'50% 20%':'50% 50%',scale:1};let x=Math.max(0,Math.min(100,Number(parts[1]))),y=Math.max(0,Math.min(100,Number(parts[2])));if(portrait&&x===50&&y===50)y=20;return{position:x+'% '+y+'%',scale:Math.max(1,Math.min(3,Number(parts[3]||1)))}}
function photoPosition(value,portrait=false){return parsePhotoCrop(value,portrait).position}
function photoScale(value){return parsePhotoCrop(value).scale}
function photoStyle(value,portrait=false){return'object-position:'+photoPosition(value,portrait)+';transform:scale('+photoScale(value)+')'}

function orderedPhotos(photos){return [...photos].sort((a,b)=>Number(Boolean(b.is_cover))-Number(Boolean(a.is_cover)))}
async function galleryPhotosForRecords(entity,records){if(!records.length)return;const ids=records.map(record=>record.id),byId=new Map(ids.map(id=>[id,[]]));const {data,error}=await state.client.from('record_photos').select('id,entity_id,photo_path,is_cover,crop_position,created_at').eq('entity',entity).in('entity_id',ids).order('created_at',{ascending:true});if(error)console.warn('A galeria unificada não está disponível na listagem.',error);else for(const photo of data||[])byId.get(photo.entity_id)?.push(photo);const legacyTable=entity==='people'?'person_photos':'vehicle_photos',foreignKey=entity==='people'?'person_id':'vehicle_id';let legacy=[];for(const [columns,sort] of [['photo_path,created_at,sort_order',['sort_order','created_at']],['photo_path,created_at',['created_at']],['photo_path',[]]]){let query=state.client.from(legacyTable).select(columns).in(foreignKey,ids);for(const column of sort)query=query.order(column,{ascending:true});const result=await query;if(!result.error){legacy=result.data||[];break}}const key=path=>externalPhotoUrl(path)||String(path||'');for(const record of records){const photos=byId.get(record.id)||[];for(const old of legacy.filter(photo=>photo[foreignKey]===record.id)){if(!old.photo_path||photos.some(photo=>key(photo.photo_path)===key(old.photo_path)))continue;photos.push({id:null,photo_path:old.photo_path,is_cover:false,crop_position:'50% 50%',created_at:old.created_at})}if(record.photo_path&&!photos.some(photo=>key(photo.photo_path)===key(record.photo_path)))photos.unshift({id:null,photo_path:record.photo_path,is_cover:!photos.some(photo=>photo.is_cover),crop_position:record.photo_position||'50% 50%'});const ordered=orderedPhotos(photos);record.photo_count=ordered.length;record.photos=ordered.slice(0,5)}const urls=await galleryPhotoUrls(records.flatMap(record=>(record.photos||[]).map(photo=>photo.photo_path)));for(const record of records)record.photos=(record.photos||[]).map(photo=>({...photo,url:urls.get(String(photo.photo_path))||''}))}
function carouselMarkup(photos,{size='detail',label='Foto',portrait=false,zoom=true,autoRotate=false}={}){if(!photos?.length)return '<div class="photo-empty">Nenhuma foto cadastrada.</div>';const cover=photos.findIndex(photo=>photo.is_cover),selected=cover>=0?cover:0,active=photos[selected],id='gallery-'+Math.random().toString(36).slice(2),auto=autoRotate&&photos.length>1,thumbnails=size==='card'?photos.map((photo,index)=>({photo,index})).filter(entry=>entry.index!==selected):photos.map((photo,index)=>({photo,index}));return '<section class="record-gallery '+(size==='card'?'record-gallery-card':'record-gallery-detail')+(portrait?' portrait-gallery':'')+'" data-photo-carousel="'+id+'" data-current-photo="'+selected+'"'+(auto?' data-auto-rotate="true" data-auto-playing="true"':'')+'><div class="carousel-stage"><button type="button" class="carousel-main"'+(zoom?' data-photo-zoom="'+esc(active.url)+'"':'')+' aria-label="'+(zoom?'Ampliar ':'Ver ')+label+' '+(selected+1)+'"><img data-carousel-main data-cache-photo-path="'+esc(active.photo_path||'')+'" src="'+esc(active.url)+'" alt="'+label+' '+(selected+1)+'" '+(size==='card'?'loading="lazy" decoding="async" ':'')+'style="'+esc(photoStyle(active.crop_position,portrait))+'"><span class="carousel-count" data-carousel-count>'+(selected+1)+' / '+photos.length+'</span></button>'+(photos.length>1?'<button type="button" class="carousel-arrow carousel-previous" data-carousel-step="-1" aria-label="Foto anterior">‹</button><button type="button" class="carousel-arrow carousel-next" data-carousel-step="1" aria-label="Próxima foto">›</button>':'')+'</div>'+(photos.length>1?'<div class="carousel-thumbnails" aria-label="Galeria de fotos">'+thumbnails.map(({photo,index})=>'<button type="button" class="carousel-thumb '+(index===selected?'active':'')+'" data-carousel-photo="'+index+'" data-photo-url="'+esc(photo.url)+'" data-photo-path="'+esc(photo.photo_path||'')+'" data-photo-position="'+esc(photo.crop_position||'50% 50%')+'" aria-label="Mostrar '+label+' '+(index+1)+'"><img src="'+esc(photo.url)+'" data-cache-photo-path="'+esc(photo.photo_path||'')+'" alt="Miniatura '+(index+1)+'" loading="lazy"><span>'+(photo.is_cover?'Capa':String(index+1))+'</span></button>').join('')+'</div>':'')+(auto?'<div class="carousel-auto-control"><button type="button" class="carousel-control-icon" data-carousel-step="-1" aria-label="Foto anterior" title="Foto anterior">‹</button><button type="button" class="carousel-control-icon" data-carousel-toggle aria-label="Pausar carrossel" title="Pausar carrossel" aria-pressed="true">Ⅱ</button><button type="button" class="carousel-control-icon" data-carousel-step="1" aria-label="Próxima foto" title="Próxima foto">›</button></div>':'')+'</section>'}
function galleryMarkup(photos,portrait=false){return carouselMarkup(orderedPhotos(photos),{portrait,label:portrait?'Foto do indivíduo':'Foto'})}
function editPhotoGalleryMarkup(photos){if(!photos.length)return '<p class="muted">Este cadastro ainda não possui fotos.</p>';return '<div class="edit-photo-gallery '+(state.page==='people'?'person-photo-gallery':'vehicle-photo-gallery')+'">'+photos.map((photo,index)=>'<article class="edit-photo-card photo-item" data-edit-photo-card="'+esc(photo.id||'')+'" data-photo-crop-position="'+esc(photo.crop_position||'50% 50%')+'"><div class="edit-photo-image-wrap"><button type="button" class="photo-zoom edit-photo-image" data-photo-zoom="'+esc(photo.url)+'" aria-label="Ampliar foto atual '+(index+1)+'"><img src="'+esc(photo.url)+'" alt="Foto atual '+(index+1)+'" style="'+esc(photoStyle(photo.crop_position))+'" loading="lazy"></button>'+(isAdmin()&&photo.id?'<button type="button" class="crop-inline-open" data-photo-crop-open="'+esc(photo.id)+'" aria-label="Ajustar enquadramento diretamente na foto" title="Ajustar diretamente na foto">✥</button><div class="crop-inline-controls" data-crop-inline-controls hidden><span>Arraste ou use pinça para enquadrar</span><button type="button" class="button secondary small" data-crop-inline-cancel>Cancelar</button><button type="button" class="button small" data-crop-inline-save>Salvar ajuste</button></div>':'')+'</div><div class="edit-photo-actions">'+(isAdmin()?'<label><input type="radio" name="editCoverPhoto" value="'+index+'" data-edit-cover-path="'+esc(photo.photo_path)+'" '+(photo.is_cover?'checked':'')+'> Capa</label><label class="delete-photo-choice"><input type="checkbox" data-edit-delete-photo="'+esc(photo.id||'legacy')+'" data-delete-path="'+esc(photo.photo_path)+'"> Excluir</label>':(photo.is_cover?'<span class="muted">Capa</span>':''))+'</div></article>').join('')+'</div>'}

function selectCarouselPhoto(carousel,index){const thumbs=[...carousel.querySelectorAll('[data-carousel-photo]')];if(!thumbs.length)return;index=(index+thumbs.length)%thumbs.length;const thumb=thumbs[index],main=carousel.querySelector('[data-carousel-main]'),zoom=carousel.querySelector('[data-photo-zoom]');main.src=thumb.dataset.photoUrl;main.alt='Foto '+(index+1);main.style.objectPosition=photoPosition(thumb.dataset.photoPosition||'50% 50%');main.style.transform='scale('+photoScale(thumb.dataset.photoPosition||'50% 50%')+')';main.dataset.cachePhotoPath=thumb.dataset.photoPath||'';if(zoom)zoom.dataset.photoZoom=thumb.dataset.photoUrl;carousel.dataset.currentPhoto=String(index);carousel.querySelector('[data-carousel-count]').textContent=(index+1)+' / '+thumbs.length;thumbs.forEach((item,i)=>item.classList.toggle('active',i===index));thumb.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'})}
function wireCarousels(){document.querySelectorAll('[data-photo-carousel]').forEach(carousel=>{if(carousel.dataset.swipeReady)return;carousel.dataset.swipeReady='true';let start=0;const stage=carousel.querySelector('.carousel-stage');stage?.addEventListener('touchstart',event=>{start=event.changedTouches[0].clientX},{passive:true});stage?.addEventListener('touchend',event=>{const delta=event.changedTouches[0].clientX-start;if(Math.abs(delta)>45)selectCarouselPhoto(carousel,Number(carousel.dataset.currentPhoto||0)+(delta<0?1:-1))},{passive:true});if(carousel.dataset.autoRotate==='true')carousel._autoRotateTimer=window.setInterval(()=>{if(!carousel.isConnected){window.clearInterval(carousel._autoRotateTimer);return}if(carousel.dataset.autoPlaying==='true'&&document.visibilityState==='visible')selectCarouselPhoto(carousel,Number(carousel.dataset.currentPhoto||0)+1)},10000)})}
async function countPeopleWithPhotosFallback(){const pageSize=500;let offset=0,total=0,recordsAvailable=true,legacyAvailable=true;while(true){const {data,error}=await state.client.from('people').select('id,photo_path').is('archived_at',null).order('id').range(offset,offset+pageSize-1);if(error)throw error;const people=data||[];if(!people.length)break;const ids=people.map(person=>person.id),activeIds=new Set(ids),withPhoto=new Set(people.filter(person=>String(person.photo_path||'').trim()).map(person=>person.id));const collect=async(table,key,entity)=>{let start=0;while(true){let query=state.client.from(table).select(key).not('photo_path','is',null).neq('photo_path','').in(key,ids);if(entity)query=query.eq('entity',entity);const result=await query.order(key,{ascending:true}).range(start,start+pageSize-1);if(result.error)return result.error;for(const row of result.data||[]){if(activeIds.has(row[key]))withPhoto.add(row[key])}const rows=result.data||[];if(rows.length<pageSize)return null;start+=pageSize}};if(recordsAvailable){const error=await collect('record_photos','entity_id','people');if(error){recordsAvailable=false;console.warn('Não foi possível contar fotos da galeria atual.',error)}}if(legacyAvailable){const error=await collect('person_photos','person_id',null);if(error){legacyAvailable=false;console.warn('Não foi possível consultar a galeria antiga de indivíduos.',error)}}total+=withPhoto.size;if(people.length<pageSize)break;offset+=pageSize}return{count:total,complete:recordsAvailable&&legacyAvailable}}
let dashboardPhotoStatsCache=null,dashboardPhotoStatsAt=0,dashboardPhotoStatsPromise=null;
async function countPeopleWithPhotos(){
  const {data,error}=await state.client.rpc('count_people_with_photos');
  if(!error&&data!==null&&data!==undefined){const count=Number(data);return{count:Number.isFinite(count)?count:null,complete:Number.isFinite(count)}}
  console.warn('A contagem otimizada de fotos não está disponível; usando a consulta compatível.',error);
  return countPeopleWithPhotosFallback();
}
function updateDashboardPhotoStats(stats){
  if(state.page!=='dashboard')return;
  const count=$('#dashboardPhotoCount'),note=$('#dashboardCountNote');
  if(count)count.textContent=stats.complete&&stats.count!==null?Number(stats.count).toLocaleString('pt-BR'):'—';
  if(note){note.textContent=stats.complete?'':'Contagem de fotos indisponível agora.';note.hidden=stats.complete}
}
async function refreshDashboardPhotoStats(){
  if(dashboardPhotoStatsPromise)return dashboardPhotoStatsPromise;
  dashboardPhotoStatsPromise=(async()=>{
    let stats;
    try{stats=await countPeopleWithPhotos()}catch(error){console.warn('Não foi possível calcular o total de indivíduos com foto.',error);stats={count:null,complete:false}}
    dashboardPhotoStatsCache=stats;dashboardPhotoStatsAt=Date.now();updateDashboardPhotoStats(stats);return stats;
  })().finally(()=>{dashboardPhotoStatsPromise=null});
  return dashboardPhotoStatsPromise;
}
let dashboardRenderToken=0;
async function renderDashboard(){
  const token=++dashboardRenderToken,photoStats=dashboardPhotoStatsCache,stale=!photoStats||Date.now()-dashboardPhotoStatsAt>30000,photoCount=photoStats&&photoStats.complete&&photoStats.count!==null?Number(photoStats.count).toLocaleString('pt-BR'):'…';
  frame('<section class="dashboard-intro"><h1>Dashboard</h1><p>Resumo dos cadastros ativos.</p></section><div class="dashboard-cards"><button class="dashboard-card" data-page="people"><span class="dashboard-icon">'+personIcon()+'</span><span class="dashboard-label">Indivíduos cadastrados</span><strong id="dashboardPeopleCount">…</strong><span class="dashboard-substats"><span class="dashboard-substat"><strong id="dashboardPhotoCount">'+photoCount+'</strong><small>Com foto</small></span><span class="dashboard-substat"><strong id="dashboardCpfCount">…</strong><small>Com CPF cadastrado</small></span></span><span class="dashboard-count-note" id="dashboardCountNote"'+(photoStats?.complete?' hidden':'')+'>'+(photoStats&&!photoStats.complete?'Contagem de fotos indisponível agora.':'Atualizando fotos em segundo plano…')+'</span><span class="dashboard-link">Abrir cadastros →</span></button><button class="dashboard-card" data-page="vehicles"><span class="dashboard-icon">'+carIcon()+'</span><span class="dashboard-label">Veículos cadastrados</span><strong id="dashboardVehicleCount">…</strong><span class="dashboard-link">Abrir veículos →</span></button><button class="dashboard-card" data-page="warrants"><span class="dashboard-icon" aria-hidden="true">⚖</span><span class="dashboard-label">Mandados de prisão ativos</span><strong id="dashboardWarrantCount">…</strong><span class="dashboard-link">Abrir mandados →</span></button></div>');
  if(stale)void refreshDashboardPhotoStats();
  const [peopleResult,cpfResult,vehicleResult,warrantResult]=await Promise.all([
    state.client.from('people').select('id',{count:'exact',head:true}).is('archived_at',null),
    state.client.from('people').select('id',{count:'exact',head:true}).is('archived_at',null).not('cpf_digits','is',null).neq('cpf_digits',''),
    state.client.from('vehicles').select('id',{count:'exact',head:true}).is('archived_at',null),
    state.client.rpc('count_active_arrest_warrants')
  ]);
  if(token!==dashboardRenderToken||state.page!=='dashboard')return;
  const number=value=>Number(value||0).toLocaleString('pt-BR');
  if(peopleResult.error||cpfResult.error||vehicleResult.error||warrantResult.error){
    for(const id of ['dashboardPeopleCount','dashboardCpfCount','dashboardVehicleCount','dashboardWarrantCount']){const el=document.getElementById(id);if(el)el.textContent='—'}
    const note=$('#dashboardCountNote');if(note){note.hidden=false;note.textContent='Não foi possível atualizar todos os totais. Reabra o Dashboard para tentar novamente.'}
    return;
  }
  const people=$('#dashboardPeopleCount'),cpf=$('#dashboardCpfCount'),vehicles=$('#dashboardVehicleCount'),warrants=$('#dashboardWarrantCount');
  if(people)people.textContent=number(peopleResult.count);if(cpf)cpf.textContent=number(cpfResult.count);if(vehicles)vehicles.textContent=number(vehicleResult.count);if(warrants)warrants.textContent=number(warrantResult.data);
}
function cardPhotoGallery(photos,label,portrait=false,total=photos?.length||0){if(!photos?.length)return '';const coverIndex=photos.findIndex(photo=>photo.is_cover),cover=photos[coverIndex>=0?coverIndex:0],ordered=coverIndex>0?[cover,...photos.filter((_,index)=>index!==coverIndex)]:photos,shown=ordered.slice(1,6);return '<div class="card-photo-gallery '+(portrait?'portrait-card-gallery':'')+'"><div class="card-photo-cover"><img data-cache-photo-path="'+esc(cover.photo_path||'')+'" src="'+esc(cover.url)+'" alt="'+esc(label)+'" loading="lazy" decoding="async" fetchpriority="low" style="'+esc(photoStyle(cover.crop_position,portrait))+'"></div>'+(shown.length?'<div class="card-photo-thumbnails" aria-label="Até cinco miniaturas de '+esc(label)+'">'+shown.map((photo,index)=>'<span class="card-photo-thumbnail"><img data-cache-photo-path="'+esc(photo.photo_path||'')+'" src="'+esc(photo.url)+'" alt="'+esc(label)+' miniatura '+(index+1)+'" loading="lazy" decoding="async" fetchpriority="low" style="'+esc(photoStyle(photo.crop_position,portrait))+'"></span>').join('')+'</div>':'')+(total>6?'<div class="card-photo-more">Mais '+(total-6)+' foto(s)</div>':'')+'</div>'}
function personCard(p){const fallback=esc(String(p.full_name||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()),photos=p.photos?.length?p.photos:p.photo_url?[{url:p.photo_url,is_cover:true,crop_position:p.photo_position||'50% 20%'}]:[],gallery=photos.length?cardPhotoGallery(photos,'Foto de '+(p.full_name||'indivíduo'),true,p.photo_count||photos.length):'<div class="avatar">'+fallback+'</div>',warrantNotice=Number(p.warrant_alert_count||0)?'<span class="warrant-card-alert">Aviso de mandado de prisão · confira na fonte oficial</span>':'';return '<article class="person-card" data-open-person="'+p.id+'" tabindex="0" role="button" aria-label="Abrir cadastro de '+esc(p.full_name)+'">'+gallery+warrantNotice+'<h3>'+esc(p.full_name)+'</h3><div class="card-meta">CPF: '+esc(p.cpf_digits?formatCpf(p.cpf_digits):'—')+'</div><div class="card-meta">RG: '+esc(p.rg||'—')+'</div></article>'}
function personIcon(){return '<svg class="menu-svg" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 12a4.2 4.2 0 1 0 0-8.4 4.2 4.2 0 0 0 0 8.4Zm0 2c-4.4 0-8 2.4-8 5.4V22h16v-2.6c0-3-3.6-5.4-8-5.4Z"/></svg>'}
function carIcon(){return '<svg class="car-icon" viewBox="0 0 64 40" aria-hidden="true"><path d="M11 25 16 12c1-3 4-5 7-5h18c3 0 6 2 7 5l5 13 4 3v8h-5a7 7 0 0 1-14 0H26a7 7 0 0 1-14 0H7v-8l4-3Zm8-2h27l-3-9c-.4-1-1-2-2-2H23c-1 0-2 1-2 2l-2 9Zm0 12a3 3 0 1 0 6 0 3 3 0 0 0-6 0Zm25 0a3 3 0 1 0 6 0 3 3 0 0 0-6 0Z"/></svg>'}function vehicleRow(v){const photos=v.photos?.length?v.photos:v.photo_url?[{url:v.photo_url,is_cover:true,crop_position:v.photo_position||'50% 50%'}]:[];return '<article class="vehicle-card" data-open-vehicle="'+v.id+'" tabindex="0" role="button" aria-label="Abrir veículo '+esc(v.plate)+'">'+(photos.length?cardPhotoGallery(photos,'Foto do veículo',false,v.photo_count||photos.length):'<div class="vehicle-placeholder">'+carIcon()+'</div>')+'<div class="vehicle-card-copy"><h3>'+esc(v.plate)+'</h3><p>'+esc([v.make,v.model,v.color].filter(Boolean).join(' · ')||'Sem marca, modelo ou cor informados')+'</p></div></article>'}
function searchBox(placeholder){return '<div class="search-control"><input class="search" id="search" type="search" placeholder="⌕  '+placeholder+'" value="'+esc(state.searchInput)+'" autocomplete="off" aria-label="Pesquisar cadastro"><button class="button search-button" id="searchButton" type="button" aria-label="Pesquisar" title="Pesquisar">⌕</button></div><p class="search-hint" id="searchHint" role="status" aria-live="polite">'+(state.searchLoading?'Buscando…':state.searchInput&&!isUsefulSearch(state.searchInput)?'Digite ao menos 3 caracteres úteis.':'')+'</p>'}
