function paginationMarkup(total,page,pageSize){const pages=Math.max(1,Math.ceil(total/pageSize));return '<div class="pagination-controls"><div class="pagination"><button class="button secondary small" data-list-page="'+(page-1)+'" '+(page===0?'disabled':'')+'>← Anterior</button><label class="page-jump-control"><span>Página</span><select class="page-select" id="pageJump" aria-label="Ir para página">'+Array.from({length:pages},(_,index)=>'<option value="'+(index+1)+'" '+(page===index?'selected':'')+'>'+(index+1)+'</option>').join('')+'</select><span>de '+pages+'</span></label><button class="button secondary small" data-list-page="'+(page+1)+'" '+(page>=pages-1?'disabled':'')+'>Próxima →</button></div></div>'}
async function loadRecordCovers(entity,records){if(!records.length)return;const {data,error}=await state.client.from('record_photos').select('entity_id,photo_path,crop_position,is_cover,created_at').eq('entity',entity).in('entity_id',records.map(record=>record.id)).order('created_at',{ascending:true});if(error)throw error;const covers=new Map();for(const photo of data||[]){const current=covers.get(photo.entity_id);if(!current||photo.is_cover)covers.set(photo.entity_id,photo)}const paths=records.map(record=>covers.get(record.id)?.photo_path||record.photo_path).filter(Boolean),urls=await galleryPhotoUrls(paths);for(const record of records){const photo=covers.get(record.id),path=photo?.photo_path||record.photo_path;record.photo_cache_path=path||'';record.photo_url=path?urls.get(String(path))||'':'';record.photo_position=photo?.crop_position||record.photo_position||'50% 50%'}}
function hydrateCardGalleries(entity,records){if(!records.length)return;const people=entity==='people',selector=people?'[data-open-person]':'[data-open-vehicle]',render=people?personCard:vehicleRow,key=people?'openPerson':'openVehicle',byId=new Map(records.map(record=>[String(record.id),record]));const hydrate=async(card,record)=>{if(!card.isConnected||card.dataset.galleryLoading==='true')return;card.dataset.galleryLoading='true';try{await galleryPhotosForRecords(entity,[record]);if(!card.isConnected)return;const template=document.createElement('template');template.innerHTML=render(record);const replacement=template.content.firstElementChild;if(replacement){replacement.dataset.galleryLoaded='true';card.replaceWith(replacement)}}catch(error){delete card.dataset.galleryLoading;console.warn('Não foi possível carregar a galeria deste cartão.',error)}};const cards=[...document.querySelectorAll(selector)].filter(card=>byId.has(card.dataset[key])&&card.dataset.galleryLoaded!=='true');if(!('IntersectionObserver'in window)){void Promise.all(cards.map(card=>hydrate(card,byId.get(card.dataset[key]))));return}const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;observer.unobserve(entry.target);void hydrate(entry.target,byId.get(entry.target.dataset[key]))}},{rootMargin:'320px 0px',threshold:0.01});for(const card of cards)observer.observe(card)}
async function renderRecords(){const people=state.page==='people',source=(people?state.people:state.vehicles).slice();const cmp=new Intl.Collator('pt-BR',{sensitivity:'base',numeric:true});source.sort((a,b)=>cmp.compare(people?a.full_name||'':a.plate||'',people?b.full_name||'':b.plate||''));let filtered=source;if(people&&state.letter!=='all'&&!state.serverPaged)filtered=source.filter(p=>foldName(p.full_name).startsWith(state.letter));const total=state.serverPaged?state.listTotal:filtered.length;const pages=Math.max(1,Math.ceil(total/state.listPageSize));state.listPage=Math.min(state.listPage,pages-1);const start=state.listPage*state.listPageSize,visible=state.serverPaged?source:filtered.slice(start,start+state.listPageSize);if(visible.length)await loadRecordCovers(people?'people':'vehicles',visible);if(people&&visible.length){try{const alerts=await loadWarrantBadgeCounts(visible.map(person=>person.id));for(const person of visible)person.warrant_alert_count=alerts[person.id]||0}catch(error){console.warn('Não foi possível carregar os avisos de mandado.',error)}}const relatedRecords=isUsefulSearch(state.query)?(people?state.vehicles.slice(0,8):state.people.slice(0,8)):[];if(relatedRecords.length)await loadRecordCovers(people?'vehicles':'people',relatedRecords);const related=isUsefulSearch(state.query)?people?'<div class="section-heading"><h2>Veículos relacionados ('+state.vehicles.length+')</h2></div><div class="cards vehicle-cards">'+(relatedRecords.length?relatedRecords.map(vehicleRow).join(''):'<div class="empty">Nenhum veículo encontrado para esta pesquisa.</div>')+'</div>':'<div class="section-heading"><h2>Pessoas encontradas ('+state.people.length+')</h2></div><div class="cards individual-cards">'+(relatedRecords.length?relatedRecords.map(personCard).join(''):'<div class="empty">Nenhuma pessoa encontrada.</div>')+'</div>':'';const subtitle=people?'Pesquise e filtre os indivíduos por nome, CPF, RG ou endereço.':'Pesquise veículos por placa, modelo, pessoa ou endereço.';const records='<div class="cards '+(people?'individual-cards':'vehicle-cards')+'">'+(visible.length?visible.map(people?personCard:vehicleRow).join(''):'<div class="empty">'+(state.query.length>0&&!isUsefulSearch(state.query)?'Digite ao menos 3 caracteres úteis.':people?'Nenhum indivíduo encontrado nesta letra.':'Nenhum veículo encontrado.')+'</div>')+'</div>';const searchElement=$('#search'),restoreSearchFocus=!!searchElement&&document.activeElement===searchElement,searchCursor=restoreSearchFocus?{start:searchElement.selectionStart,end:searchElement.selectionEnd,direction:searchElement.selectionDirection}:null;frame('<div class="page-intro"><div><h1>'+(people?'Indivíduos':'Veículos')+'</h1><p>'+subtitle+'</p></div><button class="button" data-add="'+(people?'person':'vehicle')+'">＋ Adicionar</button></div>'+searchBox(people?'Buscar indivíduo, endereço, CPF ou placa':'Buscar placa, modelo, pessoa, CPF ou endereço')+(people?'<div class="alphabet-toolbar">'+alphabetBar()+pageSizeControl(state.listPageSize)+'</div>':pageSizeControl(state.listPageSize))+(isUsefulSearch(state.query)?'<h2 class="result-heading">'+(people?'Indivíduos':'Veículos')+' encontrados ('+filtered.length+')</h2>':'')+records+paginationMarkup(total,state.listPage,state.listPageSize)+related  );if(searchCursor){const restored=$('#search');if(restored){restored.focus({preventScroll:true});restored.setSelectionRange(searchCursor.start,searchCursor.end,searchCursor.direction)}}wireSearch();wireCarousels();void Promise.all([hydrateCardGalleries(people?'people':'vehicles',visible),hydrateCardGalleries(people?'vehicles':'people',relatedRecords)])}
function foldName(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleUpperCase('pt-BR')}
function formatCpf(cpf){const d=String(cpf||'').replace(/\D/g,'');return d.length===11?d.slice(0,3)+'.'+d.slice(3,6)+'.'+d.slice(6,9)+'-'+d.slice(9):d}
function wireSearch(){const input=$('#search'),button=$('#searchButton');if(!input)return;const run=async(force=false)=>{state.searchInput=input.value;state.query=input.value.trim();state.listPage=0;state.letter='all';const key=state.page+'|'+state.query;const request=++state.searchRequest;state.searchLoading=true;const hint=$('#searchHint');if(hint)hint.textContent=state.query&&!isUsefulSearch(state.query)?'Digite ao menos 3 caracteres úteis.':state.query?'Buscando…':'';if(state.query&&!isUsefulSearch(state.query)){state.lastSearchKey=key;state.searchLoading=false;state.serverPaged=false;state.listTotal=0;state.people=[];state.vehicles=[];await renderRecords();return}if(!force&&key===state.lastSearchKey){state.searchLoading=false;return}if(button)button.disabled=true;try{await loadRecords(request);if(request!==state.searchRequest)return;state.lastSearchKey=key;await renderRecords()}catch(error){if(request===state.searchRequest){state.searchLoading=false;const status=$('#searchHint');if(status)status.textContent='Não foi possível concluir a pesquisa. Tente novamente.';toast(msg(error))}}finally{if(request===state.searchRequest){state.searchLoading=false;const active=$('#searchButton');if(active)active.disabled=false;const status=$('#searchHint');if(status)status.textContent=state.query&&!isUsefulSearch(state.query)?'Digite ao menos 3 caracteres úteis.':state.query?'Pesquisa concluída.':''}}};input.addEventListener('input',()=>{state.searchInput=input.value;clearTimeout(state.searchTimer);state.searchTimer=setTimeout(()=>void run(false),500)});input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();clearTimeout(state.searchTimer);void run(true)}});button?.addEventListener('click',()=>{clearTimeout(state.searchTimer);void run(true)})}
function photoVisualHashes(bitmap){const canvas=document.createElement('canvas');canvas.width=9;canvas.height=8;const context=canvas.getContext('2d',{willReadFrequently:true});if(!context)return{};context.drawImage(bitmap,0,0,9,8);const data=context.getImageData(0,0,9,8).data,luma=[];for(let i=0;i<data.length;i+=4)luma.push(Math.round(data[i]*.299+data[i+1]*.587+data[i+2]*.114));let difference=0n,average=0n;for(let y=0;y<8;y++)for(let x=0;x<8;x++){const index=y*9+x;difference=(difference<<1n)|BigInt(luma[index]>luma[index+1]?1:0)}const mean=luma.reduce((sum,value)=>sum+value,0)/luma.length;for(const value of luma)average=(average<<1n)|BigInt(value>=mean?1:0);return{difference_hash:difference.toString(16).padStart(16,'0'),average_hash:average.toString(16).padStart(16,'0')}}
async function pdfPhotoData(photo,index){const response=await fetch(photo.url,{mode:'cors',credentials:'omit'});if(!response.ok)throw new Error('Não foi possível carregar a foto '+(index+1)+' para o PDF.');const bitmap=await createImageBitmap(await response.blob()),fingerprints=photoVisualHashes(bitmap),ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));canvas.getContext('2d',{alpha:false}).drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',0.88));if(!blob)throw new Error('Não foi possível preparar uma foto para o PDF.');return{bytes:new Uint8Array(await blob.arrayBuffer()),width:canvas.width,height:canvas.height,is_cover:Boolean(photo.is_cover),association_photo:Boolean(photo.association_photo),dedupe_group:photo.dedupe_group||'record',...fingerprints,label:photo.pdf_label||(photo.is_cover?'Foto de capa':'Fotografia '+(index+1))}}
function downloadPdf(blob,filename){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function renderPdfPrintPreview(container,pages){
 container.replaceChildren();
 pages.slice(0,1).forEach((page,pageIndex)=>{
  const canvas=document.createElement('canvas');
  canvas.className='pdf-print-page';
  canvas.width=1190;canvas.height=1684;
  canvas.setAttribute('role','img');
  canvas.setAttribute('aria-label','Prévia completa da folha A4, página '+(pageIndex+1));
  container.append(canvas);
  const context=canvas.getContext('2d',{alpha:false});
  if(!context)return;
  context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.scale(2,2);
  const imageLoads=page.images.map(item=>new Promise(resolve=>{
   const photo=item.photo;
   if(!photo?.bytes){resolve(null);return}
   const url=URL.createObjectURL(new Blob([photo.bytes],{type:'image/jpeg'})),image=new Image();
   image.onload=()=>resolve({image,item,url});
   image.onerror=()=>{URL.revokeObjectURL(url);resolve(null)};
   image.src=url;
  }));
  Promise.all(imageLoads).then(loaded=>{
   for(const result of loaded){if(result)context.drawImage(result.image,result.item.x,842-result.item.y-result.item.height,result.item.width,result.item.height)}
   for(const item of page.texts){
    context.fillStyle='rgb('+item.color.map(value=>Math.round(Math.max(0,Math.min(1,value))*255)).join(',')+')';
    context.font=item.size+'px Arial, Helvetica, sans-serif';context.textBaseline='alphabetic';
    context.fillText(item.text,item.x,842-item.y)
   }
   for(const result of loaded)if(result)URL.revokeObjectURL(result.url)
  })
 })
}
function openPdfShareDialog(blob,filename,title,previewPages=[]){const url=URL.createObjectURL(blob),dialog=document.createElement('dialog');dialog.className='pdf-share-dialog';dialog.innerHTML='<div class="pdf-share-content"><div class="dialog-head"><div><h2>PDF pronto para compartilhar</h2><p>Prévia da primeira folha A4. O PDF completo tem '+previewPages.length+' '+(previewPages.length===1?'página.':'páginas.')+'</p></div><button type="button" class="close" data-pdf-close aria-label="Fechar">×</button></div><div class="pdf-preview-pages" data-pdf-preview aria-label="Prévia do documento"></div><div class="dialog-actions"><button type="button" class="button" data-pdf-share>Compartilhar PDF</button></div></div>';document.body.append(dialog);dialog.querySelector('[data-pdf-close]').addEventListener('click',()=>dialog.close());dialog.querySelector('[data-pdf-share]').addEventListener('click',async()=>{const file=new File([blob],filename,{type:'application/pdf'});try{if(navigator.share&&navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title,text:'Ficha do Cadastro Criminal: '+title});return}downloadPdf(blob,filename);toast('PDF baixado. Anexe-o à conversa do WhatsApp.')}catch(error){if(error.name==='AbortError')return;downloadPdf(blob,filename);toast('PDF baixado para você enviar pelo WhatsApp.')}});dialog.addEventListener('close',()=>{URL.revokeObjectURL(url);dialog.remove()},{once:true});dialog.showModal();requestAnimationFrame(()=>{if(dialog.open)renderPdfPrintPreview(dialog.querySelector('[data-pdf-preview]'),previewPages.slice(0,1))})}
function pdfRelationLabel(value){return({driver:'Condutor',owner:'Proprietário',associated:'Associado'})[value]||'Associado'}
function uniquePdfAssociationRecords(links,key){const unique=new Map();for(const link of links||[]){const related=Array.isArray(link[key])?link[key][0]:link[key];if(!related?.id)continue;let item=unique.get(related.id);if(!item){item={...related,pdf_relations:new Set(),pdf_active:false};unique.set(related.id,item)}item.pdf_relations.add(pdfRelationLabel(link.relation));item.pdf_active=item.pdf_active||Boolean(link.active)}return [...unique.values()]}
function pdfAssociationText(records,kind){if(!records.length)return kind==='vehicles'?'Nenhum veículo associado.':'Nenhuma pessoa associada.';return records.map(item=>{const details=kind==='vehicles'?[item.plate,[item.make,item.model].filter(Boolean).join(' ')].filter(Boolean).join(' — '):[item.full_name,item.cpf_digits?formatCpf(item.cpf_digits):'',item.rg?'RG '+item.rg:''].filter(Boolean).join(' — ');const relation=[...item.pdf_relations].join(', '),status=item.pdf_active?'Ativo':'Inativo';return[details||'Cadastro sem identificação',relation,status].filter(Boolean).join(' | ')}).join('\n')}
async function loadPdfAssociations(entity,id){const isPerson=entity==='people',relatedKey=isPerson?'vehicles':'people',select=isPerson?'id,relation,active,created_at,vehicles(id,plate,make,model,color,archived_at,photo_path)':'id,relation,active,created_at,people(id,full_name,cpf_digits,rg,archived_at,photo_path)';const {data,error}=await state.client.from('person_vehicle_links').select(select).eq(isPerson?'person_id':'vehicle_id',id).order('created_at',{ascending:false});if(error)throw error;return uniquePdfAssociationRecords(data,relatedKey)}
async function loadPdfWarrantsForPdf(personId){
  const {data:matches,error}=await state.client.from('arrest_warrant_matches').select('warrant_id').eq('person_id',personId).eq('review_status','confirmed');
  if(error)throw error;const ids=[...new Set((matches||[]).map(row=>row.warrant_id))];if(!ids.length)return[];
  const {data,error:warrantError}=await state.client.from('arrest_warrants').select('id,warrant_number,source_agency,source_reference,status,discharge_reported_date,discharge_reference,discharge_confirmed_date,discharge_confirmed_reference').in('id',ids);
  if(warrantError)throw warrantError;return data||[];
}
function pdfWarrantSummary(warrants){
  if(!warrants?.length)return'Nenhum vínculo de mandado foi confirmado no sistema na data de geração.';
  const statusText={pending:'Status registrado: pendente; confirmar situação na fonte oficial.',discharge_reported:'Baixa informada por operador; aguardando confirmação administrativa.',discharged:'Baixa confirmada no sistema; conferir a situação na fonte oficial.',cancelled:'Registro cancelado no sistema; conferir na fonte oficial.',revoked:'Registro revogado no sistema; conferir na fonte oficial.'};
  return warrants.map(w=>['Mandado '+(w.warrant_number||'—')+' · '+(w.source_agency||'BNMP'),statusText[w.status]||'Status: '+w.status,w.source_reference?'Referência: '+w.source_reference:'',w.status==='discharge_reported'?'Baixa informada em '+(w.discharge_reported_date?new Date(w.discharge_reported_date+'T00:00:00').toLocaleDateString('pt-BR'):'—')+' · '+(w.discharge_reference||''):w.status==='discharged'?'Baixa confirmada em '+(w.discharge_confirmed_date?new Date(w.discharge_confirmed_date+'T00:00:00').toLocaleDateString('pt-BR'):'—')+' · '+(w.discharge_confirmed_reference||''):''].filter(Boolean).join('\n')).join('\n\n')+'\n\nInformação interna. Confirme o status na fonte oficial antes de qualquer providência.';
}
