async function clearRevisionHistory(){if(!isAdmin())return;if(!confirm('Limpar permanentemente todo o histórico de versões? Esta ação não pode ser desfeita.'))return;const {error}=await state.client.rpc('admin_clear_revision_history');if(error){toast(msg(error));return}toast('Histórico de versões limpo.');await renderHistory()}
async function openPerson(id,restoring=false){if(!restoring&&!(state.page==='people'&&state.selected===id))pushAppRoute();state.page='people';state.selected=id;saveLastView();loadingPage('Abrindo cadastro…');try{const {data:p,error}=await state.client.from('people').select('*').eq('id',id).single();if(error)throw error;const {data:links,error:le}=await state.client.from('person_vehicle_links').select('id,relation,notes,active,vehicles(id,plate,make,model,color,archived_at,photo_path)').eq('person_id',id).order('created_at',{ascending:false});if(le)throw le;try{await loadRecordCovers('vehicles',(links||[]).map(link=>link.vehicles).filter(Boolean))}catch(photoError){console.warn('Não foi possível carregar as fotos dos veículos associados.',photoError)}let photos=[];try{photos=await galleryPhotos('people',p)}catch(photoError){console.warn('Não foi possível carregar a galeria do indivíduo.',photoError);if(p.photo_path)photos=[{id:null,photo_path:p.photo_path,is_cover:true,crop_position:p.photo_position||'50% 20%',url:await signedPhoto(p.photo_path)}];toast('Cadastro aberto; algumas fotos não puderam ser carregadas.')}let warrantAlertMarkup='';try{warrantAlertMarkup=await personWarrantAlertMarkup(id)}catch{}nav();frame('<button class="button secondary small" data-back>← Voltar para indivíduos</button><div class="detail-hero"><div>'+carouselMarkup(photos,{portrait:true,label:'Foto do indivíduo',autoRotate:true})+'</div><div><div class="detail-title"><div class="detail-name-copy"><h1>'+esc(p.full_name)+'</h1><button class="copy-info-button" type="button" data-copy-info="'+esc(p.full_name||'')+'" data-copy-label="Nome" title="Copiar nome" aria-label="Copiar nome">⧉</button></div><div class="detail-actions"><button class="button secondary small" data-record-pdf="people:'+id+'">Compartilhar</button><button class="button" data-edit-person="'+id+'">✎ Editar</button>'+(isAdmin()?'<button class="button danger" data-delete-record="people:'+id+'">Excluir</button>':'')+'</div></div><p class="muted">Registro criado em '+new Date(p.created_at).toLocaleDateString('pt-BR')+'</p></div></div>'+warrantAlertMarkup+'<div class="detail-sections">'+infoWithCopy('CPF',p.cpf_digits?formatCpf(p.cpf_digits):'—',p.cpf_digits)+infoWithCopy('RG',p.rg,p.rg)+info('Matrícula',p.registration)+info('Apelido/Vulgo',p.alias)+info('Aniversário',p.birthday?new Date(p.birthday+'T00:00:00').toLocaleDateString('pt-BR'):'')+personAddressInfo(p)+info('Anotações',p.notes,true)+info('Crimes',crimesDisplayText(p.occurrence_notes),true)+info('Referência da ocorrência',p.occurrence_reference,true)+'</div><div class="section-heading"><h2>Veículos associados</h2><button class="button small" data-link-person="'+id+'">＋ Associar veículo</button></div><div class="list">'+(links?.length?links.map(l=>'<div class="list-row '+(!l.active?'inactive':'')+'" data-open-vehicle="'+l.vehicles?.id+'"><div class="vehicle-thumb">'+(l.vehicles?.photo_url?'<img class="linked-vehicle-photo" data-cache-photo-path="'+esc(l.vehicles.photo_cache_path||'')+'" loading="lazy" decoding="async" src="'+esc(l.vehicles.photo_url)+'" alt="Foto do veículo '+esc(l.vehicles.plate||'')+'">':carIcon())+'</div><div><div class="row-title">'+esc(l.vehicles?.plate||'Veículo removido')+'</div><div class="row-subtitle">'+esc([l.vehicles?.make,l.vehicles?.model,l.vehicles?.color].filter(Boolean).join(' · '))+(l.active?'':' · inativo')+'</div></div>'+(l.active?'<button class="more-button" data-unlink="'+l.id+'" title="Desativar vínculo">×</button>':'')+'</div>').join(''):'<div class="empty">Nenhum veículo associado.</div>')+'</div>');saveLastView()}catch(error){state.selected=null;nav();frame('<div class="error-box">Não foi possível abrir este cadastro: '+esc(msg(error))+'</div><button class="button secondary small" data-back>← Voltar para indivíduos</button>')}wireCarousels()}
function crimesDisplayText(value){
  let text=String(value||'');
  text=text.replace(/\b(?:(?:n[º°.]?|n[uú]mero)\s*(?:do\s*)?)?(?:processo|proc\.?)\s*[:#-]?\s*[\d./-]{8,}/gi,'');
  text=text.replace(/\b(?:processo(?:\s*(?:n[º°.]?|numero))?\s*[:#-]?\s*)?\d{7}-\d{2}\.\d{4}\.\d\.\d{2}\.\d{4}(?:\.\d{2}\.\d{4}-\d{2})?\b/gi,'');
  return text.split(/\r?\n/).map(line=>line.replace(/\s+/g,' ').replace(/^[\s:;,.|–—-]+|[\s:;,.|–—-]+$/g,'').trim()).filter(line=>line&&!/^processo(?:\s|:|#|$)/i.test(line)).join('\n').trim();
}
function info(title,value,wide=false){if(!value)return '';const address=/^Endereço/.test(title),content=address?'<a href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(value)+'" target="_blank" rel="noopener noreferrer">'+esc(value)+' ↗</a>':esc(value);return '<section class="info-box '+(wide?'wide':'')+'"><div class="info-label">'+esc(title)+'</div><div class="info-value">'+content+'</div></section>'}
function infoWithCopy(title,value,copyValue){if(!value)return '';return '<section class="info-box"><div class="info-label info-label-copy"><span>'+esc(title)+'</span><button class="copy-info-button" type="button" data-copy-info="'+esc(copyValue||'')+'" data-copy-label="'+esc(title)+'" title="Copiar '+esc(title)+'" aria-label="Copiar '+esc(title)+'">⧉</button></div><div class="info-value">'+esc(value)+'</div></section>'}
async function openVehicle(id,restoring=false){if(!restoring&&!(state.page==='vehicles'&&state.selected===id))pushAppRoute();state.page='vehicles';state.selected=id;saveLastView();const {data:v,error}=await state.client.from('vehicles').select('*').eq('id',id).single();if(error){toast(msg(error));return}const {data:links,error:le}=await state.client.from('person_vehicle_links').select('id,relation,notes,active,people(id,full_name,cpf_digits,rg,photo_path,archived_at)').eq('vehicle_id',id).order('created_at',{ascending:false});if(le){toast(msg(le));return}await Promise.all((links||[]).map(async link=>{if(link.people)link.people.photo_url=await signedPhoto(link.people.photo_path)}));const photos=await galleryPhotos('vehicles',v);nav();frame('<button class="button secondary small" data-back>← Voltar para veículos</button><div class="detail-hero"><div>'+galleryMarkup(photos)+'</div><div><div class="detail-title"><h1>'+esc(v.plate)+'</h1><div class="detail-actions"><button class="button secondary small" data-record-pdf="vehicles:'+id+'">Compartilhar</button><button class="button" data-edit-vehicle="'+id+'">✎ Editar</button>'+(isAdmin()?'<button class="button danger" data-delete-record="vehicles:'+id+'">Excluir</button>':'')+'</div></div><p class="muted">'+carIcon()+' '+esc([v.make,v.model,v.color].filter(Boolean).join(' · '))+'</p></div></div><div class="detail-sections">'+info('Placa',v.plate)+info('Marca',v.make)+info('Modelo',v.model)+info('Cor',v.color)+info('Anotações',v.notes,true)+'</div><div class="section-heading"><h2>Pessoas associadas</h2><button class="button small" data-link-vehicle="'+id+'">＋ Associar pessoa</button></div><div class="list">'+(links?.length?links.map(l=>'<div class="list-row '+(!l.active?'inactive':'')+'" data-open-person="'+l.people?.id+'"><div class="vehicle-thumb">'+(l.people?.photo_url?'<img class="linked-person-photo" data-cache-photo-path="'+esc(l.people.photo_cache_path||'')+'" loading="lazy" decoding="async" src="'+esc(l.people.photo_url)+'" alt="Foto de '+esc(l.people.full_name||'Pessoa')+'">':'<span class="linked-person-icon">'+personIcon()+'</span>')+'</div><div><div class="row-title">'+esc(l.people?.full_name||'Pessoa não disponível')+'</div><div class="row-subtitle">CPF: '+esc(l.people?.cpf_digits?formatCpf(l.people.cpf_digits):'—')+(l.active?'':' · vínculo inativo')+'</div></div>'+(l.active?'<button class="more-button" data-unlink="'+l.id+'" title="Desativar vínculo">×</button>':'')+'</div>').join(''):'<div class="empty">Nenhuma pessoa associada.</div>')+'</div>');saveLastView();wireCarousels()}
async function copyToClipboard(value,message){try{await navigator.clipboard.writeText(value);toast(message)}catch{const input=document.createElement('textarea');input.value=value;input.setAttribute('readonly','');input.style.position='fixed';input.style.opacity='0';document.body.append(input);input.select();const copied=document.execCommand('copy');input.remove();toast(copied?message:'Não foi possível copiar automaticamente.')}} 
function generateTemporaryPassword(){const groups=['ABCDEFGHJKLMNPQRSTUVWXYZ','abcdefghijkmnopqrstuvwxyz','23456789','!@#$%'];const alphabet=groups.join('');const bytes=crypto.getRandomValues(new Uint8Array(36));const chars=groups.map((group,index)=>group[bytes[index]%group.length]);for(let i=4;i<20;i++)chars.push(alphabet[bytes[i]%alphabet.length]);for(let i=chars.length-1;i>0;i--){const j=bytes[20+(i%(bytes.length-20))]%(i+1);[chars[i],chars[j]]=[chars[j],chars[i]]}return chars.join('')}
async function renderTeam(){const {data,error}=await state.client.from('profiles').select('id,email,display_name,role,created_at').order('created_at',{ascending:false}).limit(250);if(error)throw error;state.profiles=data||[];let authorizedEmails=[],authorizationLoadError='';try{const authorization=await invokeUserAdmin({action:'list_google_authorized'});authorizedEmails=authorization.emails||[]}catch(error){authorizationLoadError=msg(error)}const googleForm='<form id="googleAuthorizeForm" class="user-create-row"><div class="field"><label for="manualEmail">E-mail autorizado</label><input id="manualEmail" type="email" autocomplete="email" required placeholder="nome@exemplo.com"><small>Libera o acesso com a conta Google autorizada. Nenhum e-mail é enviado.</small></div><button class="button" type="submit">＋ Autorizar e-mail</button></form>';const passwordForm='<form id="passwordUserForm" class="user-create-row"><div class="field"><label for="passwordUserEmail">E-mail do novo usuário</label><input id="passwordUserEmail" type="email" autocomplete="email" required placeholder="nome@exemplo.com"><small>Autoriza como Operador e gera um código de primeiro acesso. Nada é enviado por e-mail; compartilhe o código pelo WhatsApp.</small></div><button class="button" type="submit">＋ Autorizar e gerar código</button></form>';const activeForm=state.teamTab==='password'?passwordForm:googleForm;const users=state.profiles.map(p=>'<div class="list-row user-account-row"><div class="vehicle-thumb">'+esc((p.email||'?')[0].toUpperCase())+'</div><div><div class="row-title">'+esc(p.display_name||p.email)+'</div><div class="row-subtitle">'+esc(p.email)+' · '+esc(new Date(p.created_at).toLocaleDateString('pt-BR'))+'</div></div><select class="role-select" data-role-user="'+p.id+'" '+(p.id===state.session.user.id?'disabled':'')+'><option value="pending" '+(p.role==='pending'?'selected':'')+'>Pendente</option><option value="operator" '+(p.role==='operator'?'selected':'')+'>Operador</option><option value="admin" '+(p.role==='admin'?'selected':'')+'>Administrador</option><option value="disabled" '+(p.role==='disabled'?'selected':'')+'>Desativado</option></select>'+(p.id===state.session.user.id?'':'<button type="button" class="button danger small" data-delete-user="'+p.id+'" data-delete-email="'+esc(p.email)+'">Excluir conta</button>')+'</div>').join('');const authorizedRows=authorizedEmails.map(entry=>'<div class="list-row user-account-row"><div class="vehicle-thumb">'+esc((entry.email||'?')[0].toUpperCase())+'</div><div><div class="row-title">'+esc(entry.email)+'</div><div class="row-subtitle">Login pelo Google · '+esc(entry.role==='admin'?'Administrador':entry.role==='disabled'?'Desativado':entry.role==='pending'?'Pendente':'Operador')+'</div></div><button type="button" class="button danger small" data-revoke-google="'+esc(entry.email)+'" '+(String(entry.email).toLowerCase()===String(state.session.user.email||'').toLowerCase()?'disabled':'')+'>Revogar acesso</button></div>').join('');const empty=state.profiles.length?'':'<div class="empty">Nenhum usuário cadastrado.</div>';const emptyAuthorized=authorizedRows||'<div class="empty">Nenhum e-mail autorizado.</div>';const created=state.teamCreatedUser?'<section class="created-user-result"><div><h2>'+((state.teamCreatedUser.method==='email')?'Acesso por senha autorizado':state.teamCreatedUser.method==='google'?'E-mail autorizado para Google':'E-mail autorizado')+'</h2><p>E-mail: <strong>'+esc(state.teamCreatedUser.email)+'</strong></p><p>'+(state.teamCreatedUser.method==='google'?(state.teamCreatedUser.codeUnavailable?'O e-mail ficou autorizado para o botão “Continuar com Google”. A geração do código alternativo por senha falhou, mas não cancela a autorização Google.':'A pessoa já pode entrar pelo botão “Continuar com Google”. Nenhum e-mail é enviado.'):'Um código temporário foi gerado. Ele não aparece nesta tela; copie o convite e envie pelo WhatsApp. O operador informa o código em “Primeiro acesso” e escolhe a própria senha. Validade: 7 dias.')+' Perfil: '+esc(state.teamCreatedUser.role==='admin'?'Administrador':'Operador')+'.</p></div>'+(state.teamCreatedUser.method==='google'||state.teamCreatedUser.codeUnavailable?'':'<div class="created-user-actions"><button type="button" class="button small" id="copyWhatsAppInvite">Copiar convite para WhatsApp</button></div>')+'</section>':'';frame('<div class="page-intro"><div><h1>Usuários</h1><p>Autorize o endereço para login Google ou por senha escolhida no primeiro acesso.</p></div></div>'+'<div class="notice"><strong>Fotos duplicadas</strong><p>Confere as fotos dos indivíduos, preserva a capa e remove cópias idênticas que não sejam usadas em outro cadastro.</p><button type="button" class="button secondary small" id="dedupePeoplePhotos">Verificar e limpar fotos duplicadas</button></div>'+(state.teamTab==='password'?'<div class="notice">O acesso é criado sem enviar e-mail. Copie o convite pelo WhatsApp para entregar o código único; o operador digita o código e escolhe a própria senha.</div>':'<div class="notice">O acesso pelo Google continua igual. Também será gerado um código único para o primeiro acesso por senha; envie-o pelo WhatsApp.</div>')+(authorizationLoadError?'<div class="error-box">Não foi possível carregar os e-mails autorizados. A lista de usuários cadastrados continua disponível. Detalhe: '+esc(authorizationLoadError)+'</div>':'')+'<div class="team-tabs"><button type="button" class="team-tab '+(state.teamTab==='google'?'active':'')+'" data-team-tab="google">Conta Google</button><button type="button" class="team-tab '+(state.teamTab==='password'?'active':'')+'" data-team-tab="password">E-mail sem Google</button></div><div class="list user-table">'+activeForm+'</div>'+created+'<div class="page-intro"><div><h2>E-mails autorizados para Google</h2><p>O perfil autorizado é aplicado no primeiro login Google ou na criação de senha com o código.</p></div></div><div class="list user-table">'+emptyAuthorized+'</div><div class="page-intro"><div><h2>Usuários cadastrados</h2><p>Altere privilégios ou exclua contas.</p></div></div><div class="list user-table">'+users+empty+'</div>');document.querySelectorAll('[data-team-tab]').forEach(button=>button.onclick=async()=>{state.teamTab=button.dataset.teamTab;await renderTeam()});const googleFormEl=$('#googleAuthorizeForm');if(googleFormEl)googleFormEl.onsubmit=async e=>{e.preventDefault();const email=$('#manualEmail').value.trim().toLowerCase(),button=googleFormEl.querySelector('button[type="submit"]');if(!email)return;button.disabled=true;state.teamCreatedUser=null;try{const result=await invokeUserAdmin({action:'authorize-google',email});state.teamCreatedUser={email,role:result.role||'operator',method:'google',firstAccessCode:result.firstAccessCode,codeUnavailable:Boolean(result.codeUnavailable)};toast(result.codeUnavailable?'E-mail autorizado para Google. A etapa opcional de senha não gerou código.':'E-mail autorizado para acesso Google.');await renderTeam()}catch(error){toast(msg(error))}finally{const activeButton=$('#googleAuthorizeForm button[type="submit"]');if(activeButton)activeButton.disabled=false}};const passwordFormEl=$('#passwordUserForm');if(passwordFormEl)passwordFormEl.onsubmit=async e=>{e.preventDefault();const email=$('#passwordUserEmail').value.trim().toLowerCase(),button=passwordFormEl.querySelector('button[type="submit"]');if(!email)return;button.disabled=true;state.teamCreatedUser=null;try{const result=await invokeUserAdmin({action:'create-email-user',email});state.teamCreatedUser={email,role:result.role||'operator',method:'email',existing:Boolean(result.existing),firstAccessCode:result.firstAccessCode};toast(result.existing?'Novo código de primeiro acesso gerado.':'E-mail autorizado. Código gerado para envio pelo WhatsApp.');await renderTeam()}catch(error){toast(msg(error))}finally{const activeButton=$('#passwordUserForm button[type="submit"]');if(activeButton)activeButton.disabled=false}};const copyInvite=$('#copyWhatsAppInvite');if(copyInvite)copyInvite.onclick=()=>{const created=state.teamCreatedUser;if(!created)return;const code=String(created.firstAccessCode||'');const text='Olá! Seu acesso ao Cadastro Criminal foi autorizado.\n\nAcesse: https://tncykeyra.github.io/cadastro-individuos-app/\nE-mail: '+created.email+'\nCódigo de primeiro acesso: '+code+'\n\nAbra “Primeiro acesso”, informe o e-mail e este código e escolha uma senha com pelo menos 12 caracteres. O código vale por 7 dias e só pode ser usado uma vez. Depois, você poderá entrar com e-mail e senha. Se este endereço também estiver vinculado a uma Conta Google, o botão “Continuar com Google” continuará funcionando.\n\nSeu perfil inicial é '+(created.role==='admin'?'Administrador':'Operador')+'.';copyToClipboard(text,'Convite com código copiado para enviar pelo WhatsApp.')}}


async function invokeUserAdmin(payload){const {data,error}=await state.client.functions.invoke('invite-user',{body:payload});if(!error&&!data?.error)return data;if(data?.error)throw new Error(data.error);let detail=msg(error),status=error?.context?.status;try{const body=await error?.context?.clone?.().json();if(body?.error)detail=body.error}catch{}if(status===404)detail='O serviço de usuários ainda não foi publicado no Supabase. A implantação automática precisa ser configurada.';else if(status===401)detail='Sua sessão expirou. Entre novamente como administrador.';throw new Error(detail)}

function pretty(v){if(v===null||v===undefined||v==='')return '—';if(typeof v==='object')return JSON.stringify(v);return String(v)}
async function renderHistory(reset=true){if(reset){state.revisions=[];state.revisionOffset=0}if(!state.historyProfiles.length){const {data,error:profileError}=await state.client.from('profiles').select('id,email').order('email');if(profileError)throw profileError;state.historyProfiles=data||[]}const filters=state.revisionFilters;let query=state.client.from('record_revisions').select('id,actor_id,action,entity,entity_id,before_data,after_data,occurred_at',{count:'exact'}).order('occurred_at',{ascending:false});if(filters.entity!=='all')query=query.eq('entity',filters.entity);if(filters.action!=='all')query=query.eq('action',filters.action);if(filters.actor==='deleted')query=query.is('actor_id',null);else if(filters.actor!=='all')query=query.eq('actor_id',filters.actor);if(filters.from)query=query.gte('occurred_at',new Date(filters.from+'T00:00:00').toISOString());if(filters.to){const end=new Date(filters.to+'T00:00:00');end.setDate(end.getDate()+1);query=query.lt('occurred_at',end.toISOString())}const from=state.revisionOffset;const {data,error,count}=await query.range(from,from+99);if(error)throw error;const page=data||[];state.revisions.push(...page);state.revisionOffset+=page.length;state.revisionTotal=count||0;const rows=state.revisions,emails=Object.fromEntries(state.historyProfiles.map(profile=>[profile.id,profile.email]));const actorOptions=state.historyProfiles.map(profile=>'<option value="'+esc(profile.id)+'" '+(filters.actor===profile.id?'selected':'')+'>'+esc(profile.email||'Usuário sem e-mail')+'</option>').join('');frame('<div class="page-intro"><div><h1>Histórico e versões</h1><p>Filtre as alterações por cadastro, ação, usuário e período.</p></div><button class="button danger" data-clear-history>Limpar histórico</button></div><form id="historyFilterForm" class="history-filters"><label class="field"><span>Cadastro</span><select name="entity"><option value="all" '+(filters.entity==='all'?'selected':'')+'>Todos</option><option value="people" '+(filters.entity==='people'?'selected':'')+'>Indivíduos</option><option value="vehicles" '+(filters.entity==='vehicles'?'selected':'')+'>Veículos</option><option value="person_vehicle_links" '+(filters.entity==='person_vehicle_links'?'selected':'')+'>Associações</option></select></label><label class="field"><span>Ação</span><select name="action"><option value="all" '+(filters.action==='all'?'selected':'')+'>Todas</option><option value="insert" '+(filters.action==='insert'?'selected':'')+'>Criação</option><option value="update" '+(filters.action==='update'?'selected':'')+'>Edição</option><option value="delete" '+(filters.action==='delete'?'selected':'')+'>Exclusão</option></select></label><label class="field"><span>Usuário</span><select name="actor"><option value="all" '+(filters.actor==='all'?'selected':'')+'>Todos</option><option value="deleted" '+(filters.actor==='deleted'?'selected':'')+'>Usuário removido</option>'+actorOptions+'</select></label><label class="field"><span>De</span><input name="from" type="date" value="'+esc(filters.from)+'"></label><label class="field"><span>Até</span><input name="to" type="date" value="'+esc(filters.to)+'"></label><button class="button" type="submit">Aplicar filtros</button></form><div class="history-results" aria-live="polite">'+state.revisionOffset.toLocaleString('pt-BR')+' de '+state.revisionTotal.toLocaleString('pt-BR')+' alterações carregadas</div><div class="notice">A limpeza apaga as versões registradas e não pode ser desfeita.</div><div class="revision-list">'+(rows.length?rows.map(r=>{const before=r.before_data||{},after=r.after_data||{};const keys=[...new Set([...Object.keys(before),...Object.keys(after)])].filter(k=>!['id','created_by','created_at','updated_by','updated_at'].includes(k)&&JSON.stringify(before[k])!==JSON.stringify(after[k]));const target=after.full_name||before.full_name||after.plate||before.plate||r.entity_id;return '<details class="revision"><summary><span><strong>'+esc(target)+'</strong><small>'+esc(r.entity)+' · '+esc(r.action)+' · '+esc(emails[r.actor_id]||'usuário removido')+' · '+new Date(r.occurred_at).toLocaleString('pt-BR')+'</small></span><span class="revision-id">#'+r.id+'</span></summary><div class="revision-body">'+(keys.length?'<div class="diff-list">'+keys.map(k=>'<div class="diff-row"><strong>'+esc(k.replaceAll('_',' '))+'</strong><span>'+esc(pretty(before[k]))+'</span><span>→ '+esc(pretty(after[k]))+'</span></div>').join('')+'</div>':'<p>Cadastro criado ou sem campos alterados.</p>')+'<button class="button small" data-revert="'+r.id+'">Restaurar versão anterior</button></div></details>'}).join(''):'<div class="empty">Nenhuma alteração encontrada com esses filtros.</div>')+'</div>'+(state.revisionOffset<state.revisionTotal?'<button class="button secondary load-more" data-load-more>Carregar mais alterações</button>':'') )}
