async function findOcrMatches(kind,values){
  const candidates=new Map();let hard=false;
  const add=(rows,reason,definitive=false)=>{if(definitive&&rows?.length)hard=true;for(const record of rows||[]){const current=candidates.get(record.id)||{record,reasons:[],hard:false};if(!current.reasons.includes(reason))current.reasons.push(reason);current.hard=current.hard||definitive;candidates.set(record.id,current)}};
  if(kind==='vehicles'){
    const plate=normalizePlate(values.plate||'');if(!isValidPlate(plate))return{items:[],hard:false};
    const {data,error}=await state.client.rpc('search_vehicles',{search_term:plate,result_limit:100});if(error)return{items:[],hard:false,error};
    add((data||[]).filter(record=>normalizePlate(record.plate)===plate),'Placa exata',true);
    return{items:[...candidates.values()].map(item=>({...item,reason:item.reasons.join(' · ')})),hard};
  }
  const exact=[];
  const cpf=String(values.cpf_digits||'').replace(/\D/g,'');
  if(isValidCpf(cpf))exact.push(['CPF exato',state.client.from('people').select('id,full_name,rg,birthday,cpf_digits,registration').eq('cpf_digits',cpf).limit(8)]);
  const rg=String(values.rg||'').trim();if(rg)exact.push(['RG exato',state.client.from('people').select('id,full_name,rg,birthday,cpf_digits,registration').eq('rg',rg).limit(8)]);
  const registration=String(values.registration||'').replace(/\D/g,'');if(registration.length===11)exact.push(['Registro CNH exato',state.client.from('people').select('id,full_name,rg,birthday,cpf_digits,registration').eq('registration',registration).limit(8)]);
  const results=await Promise.all(exact.map(([,query])=>query));
  for(let index=0;index<results.length;index++){if(results[index].error)return{items:[],hard:false,error:results[index].error};add(results[index].data,exact[index][0],true)}
  const name=String(values.full_name||'').trim();
  if(name){try{const similar=await lookupSimilarPeople(name,values.birthday||'',rg);for(const record of similar){const sameName=String(record.full_name||'').trim().toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR');const sameBirthday=Boolean(values.birthday)&&String(record.birthday||'')===String(values.birthday);add([record],sameName&&sameBirthday?'Nome e nascimento coincidem; confirme os identificadores':'Nome semelhante; confirme se é a mesma pessoa',false)}}catch(error){return{items:[],hard:false,error}}}
  return{items:[...candidates.values()].map(item=>({...item,reason:item.reasons.join(' · ')})),hard};
}
function applyOcrValuesToForm(form,values){
  let applied=0;
  for(const [key,rawValue] of Object.entries(values||{})){
    const target=key==='filiation'?'notes':key;
    const control=form?.elements?.namedItem(target);if(!control||typeof control.value==='undefined'||control.disabled||control.readOnly)continue;
    let value=String(rawValue??'').trim();if(key==='birthday')value=formatBirthdayInput(value);if(key==='cpf_digits')value=value.replace(/\D/g,'');if(key==='plate')value=normalizePlate(value);if(key==='filiation')value=mergeFiliationIntoNotes(control.value,value);
    if(control.value!==value){control.value=value;control.dispatchEvent(new Event('input',{bubbles:true}));control.dispatchEvent(new Event('change',{bubbles:true}));}
    applied++;
  }
  return applied;
}
