document.addEventListener('click',async e=>{const button=e.target.closest('[data-delete-user]');if(!button||!isAdmin())return;const email=button.dataset.deleteEmail||'este usuário';if(!confirm('Excluir permanentemente a conta de '+email+'? O acesso será removido; os cadastros e fotos relacionados serão mantidos.'))return;button.disabled=true;try{await invokeUserAdmin({action:'delete',userId:button.dataset.deleteUser});toast('Conta de '+email+' excluída.');await renderTeam()}catch(error){toast(msg(error))}finally{const active=$('[data-delete-user="'+button.dataset.deleteUser+'"]');if(active)active.disabled=false}});$('#recordDialog').addEventListener('click',e=>{if(e.target===$('#recordDialog'))$('#recordDialog').close()});function showInstallHelp(){const ua=navigator.userAgent,isIOS=/iPad|iPhone|iPod/.test(ua)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1),isAndroid=/Android/i.test(ua);const instructions=isIOS?'No Safari, toque em Compartilhar e escolha “Adicionar à Tela de Início”. Depois toque em “Adicionar”.':isAndroid?'No Chrome, abra o menu ⋮ e escolha “Instalar app” ou “Adicionar à tela inicial”.': 'Abra o menu do navegador e escolha “Instalar Cadastro Criminal” ou “Instalar aplicativo”. No iPhone e iPad, use o Safari e a opção “Adicionar à Tela de Início”.';const dialog=$('#recordDialog');dialog.innerHTML='<div class="dialog-inner install-help"><div class="dialog-head"><h2>Instalar Cadastro Criminal</h2><button class="close" type="button" data-close aria-label="Fechar">×</button></div><p class="install-help-copy">'+esc(instructions)+'</p><div class="dialog-actions"><button class="button" type="button" data-close>Entendi</button></div></div>';dialog.showModal()}const isInstalled=window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;$('#installButton').hidden=isInstalled;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.install=e;$('#installButton').hidden=false});window.addEventListener('appinstalled',()=>{$('#installButton').hidden=true;state.install=null});$('#installButton').addEventListener('click',async()=>{if(!state.install){showInstallHelp();return}const promptEvent=state.install;state.install=null;await promptEvent.prompt();const result=await promptEvent.userChoice;if(result?.outcome==='accepted')$('#installButton').hidden=true;else showInstallHelp()});if('serviceWorker' in navigator&&location.protocol!=='file:'){navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!navigator.serviceWorker.controller)return;const reloadAfterDialog=()=>{if($('#recordDialog')?.open){$('#recordDialog').addEventListener('close',reloadAfterDialog,{once:true});return}if(state.selected&&['people','vehicles'].includes(state.page))saveLastView();setTimeout(()=>location.reload(),1500)};reloadAfterDialog()},{once:true});navigator.serviceWorker.register(import.meta.env.BASE_URL+'sw.js?v=30',{updateViaCache:'none'}).then(registration=>registration.update()).catch(()=>{})}
async function initialize(){if(!config.url||!config.key){frame('<div class="auth-wrap"><section class="auth-card"><div class="brand-mark auth-mark"><img src="'+appIconUrl+'" alt=""></div><h1>Cadastro Criminal</h1><p class="auth-caption">A interface está pronta para conectar ao banco em nuvem. Para ativar login e dados compartilhados, configure o projeto Supabase e as variáveis de ambiente seguindo o README.</p><div class="notice">Nenhum dado está sendo salvo neste aparelho. A conexão ao banco ainda não foi configurada.</div></section></div>')}else{state.client=createClient(config.url,config.key,{auth:{storage:window.localStorage,persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});state.passwordSetup=/#.*type=(invite|recovery)/.test(location.hash);const {data:{session}}=await state.client.auth.getSession();state.session=session;state.client.auth.onAuthStateChange((event,newSession)=>{if(event==='INITIAL_SESSION'||event==='TOKEN_REFRESHED')return;if(event==='PASSWORD_RECOVERY')state.passwordSetup=true;setTimeout(()=>loadUser(newSession),0)});await loadUser(session)}}

document.addEventListener('click',event=>{const button=event.target.closest('[data-record-pdf]');if(!button)return;const [entity,id]=button.dataset.recordPdf.split(':');if(['people','vehicles'].includes(entity)&&id)void generateRecordPdf(entity,id)});

document.addEventListener('input',event=>{
  const input=event.target.closest?.('[data-warrant-pdf-batch-field]');if(!input)return;
  const index=Number(input.dataset.index),entry=warrantPdfBatch[index];if(!entry)return;
  entry.values=entry.values||{};entry.values[input.dataset.warrantPdfBatchField]=input.value;
});
document.addEventListener('change',async event=>{
  const input=event.target;
  if(input.matches?.('[data-warrant-pdf-batch]')){
    if(!isAdmin()){toast('Apenas administradores podem importar PDFs.');return}
    try{await readWarrantPdfBatch(input.files||[])}catch(error){toast(msg(error))}finally{input.value=''}
    return;
  }
  if(!input.matches?.('[data-warrant-csv]'))return;
  if(!isAdmin()){toast('Apenas administradores podem importar listas.');return}
  const file=input.files?.[0];if(!file)return;
  try{if(file.size>10*1024*1024)throw new Error('O CSV deve ter até 10 MB.');const parsed=await warrantReadCsv(file);warrantImportPreview={fileName:file.name,parsed};await renderWarrants()}
  catch(error){warrantImportPreview=null;toast(msg(error))}
});
document.addEventListener('change',async event=>{
  const input=event.target;if(!input.matches?.('#warrantManualPdf'))return;
  if(!isAdmin())return;
  const file=input.files?.[0];if(!file)return;
  try{await readWarrantPdf()}catch(error){const status=$('#warrantPdfOcrStatus');if(status)status.textContent='Não foi possível ler o PDF localmente. Confira o arquivo e tente novamente.';toast(msg(error))}
});
document.addEventListener('click',async event=>{
  const target=event.target;
  const wrap=async action=>{try{await action()}catch(error){toast(msg(error))}};
  const removePdf=target.closest('[data-warrant-pdf-remove]');if(removePdf){if(!isAdmin()||warrantPdfBatchSaving)return;warrantPdfBatch.splice(Number(removePdf.dataset.warrantPdfRemove),1);await renderWarrants();return}
  if(target.closest('[data-warrant-clear-pdf-batch]')){if(!isAdmin()||warrantPdfBatchSaving)return;warrantPdfBatch=[];await renderWarrants();return}
  if(target.closest('[data-warrant-save-pdf-batch]')){await wrap(saveWarrantPdfBatch);return}
  if(target.closest('[data-warrant-import]')){await wrap(warrantImportCsv);return}
  if(target.closest('[data-warrant-cancel-import]')){warrantImportPreview=null;await renderWarrants();return}
  const search=target.closest('[data-warrant-search]');if(search){await wrap(()=>findWarrantPerson(search.dataset.warrantSearch));return}
  const link=target.closest('[data-warrant-link]');if(link){await wrap(()=>addWarrantCandidate(link.dataset.warrantLink,link.dataset.warrantPerson));return}
  const review=target.closest('[data-warrant-review]');if(review){await wrap(()=>reviewWarrantMatch(review));return}
  const editWarrant=target.closest('[data-warrant-edit]');if(editWarrant){showWarrantEditDialog(editWarrant.dataset.warrantEdit);return}
  const deleteAllWarrants=target.closest('[data-warrant-delete-all]');if(deleteAllWarrants){showWarrantDeleteAllDialog();return}const deleteWarrant=target.closest('[data-warrant-delete]');if(deleteWarrant){showWarrantDeleteDialog(deleteWarrant.dataset.warrantDelete);return}
  const report=target.closest('[data-warrant-discharge]');if(report){showWarrantReportDialog(report.dataset.warrantDischarge);return}
  const confirmDischarge=target.closest('[data-warrant-confirm-discharge]');if(confirmDischarge){showWarrantConfirmDialog(confirmDischarge);return}
  const approveProposal=target.closest('[data-warrant-proposal-approve]');if(approveProposal){await wrap(()=>approveWarrantPersonProposal(approveProposal.dataset.warrantProposalApprove,approveProposal.dataset.proposalName));return}
  const rejectProposal=target.closest('[data-warrant-proposal-reject]');if(rejectProposal){await wrap(()=>rejectWarrantPersonProposal(rejectProposal.dataset.warrantProposalReject));return}
  const pdf=target.closest('[data-warrant-doc]');if(pdf){await wrap(()=>openWarrantDocument(pdf.dataset.warrantPath));return}
  if(target.closest('[data-warrant-read-pdf]')){await wrap(readWarrantPdf);return}
});
async function approveWarrantPersonProposal(proposalId,fullName){
  if(!isAdmin())throw new Error('Apenas administradores podem aprovar novos indivíduos.');
  if(!window.confirm('Aprovar a proposta e criar o cadastro de '+(fullName||'indivíduo')+'? O mandado será vinculado ao novo cadastro.'))return;
  const {data,error}=await state.client.rpc('admin_approve_arrest_warrant_person_proposal',{p_proposal_id:proposalId});if(error)throw error;
  toast('Cadastro aprovado e criado. O mandado foi vinculado ao indivíduo.');await renderWarrants();
}
async function rejectWarrantPersonProposal(proposalId){
  if(!isAdmin())throw new Error('Apenas administradores podem rejeitar propostas.');
  const notes=window.prompt('Motivo da rejeição (opcional):','');if(notes===null)return;
  const {error}=await state.client.rpc('admin_reject_arrest_warrant_person_proposal',{p_proposal_id:proposalId,p_review_notes:notes.trim()});if(error)throw error;
  toast('Proposta rejeitada.');await renderWarrants();
}
document.addEventListener('submit',async event=>{
  const form=event.target;if(!form?.id)return;
  const handlers={warrantManualForm:saveWarrantManual,warrantEditForm:saveWarrantEdit,warrantDeleteForm:submitWarrantDelete,warrantDeleteAllForm:submitWarrantDeleteAll,warrantReportForm:submitWarrantReport,warrantConfirmForm:submitWarrantConfirmation};
  const handler=handlers[form.id];if(!handler)return;event.preventDefault();
  try{await handler(event)}catch(error){toast(msg(error))}
});

initialize().catch(error=>{console.error(error);frame('<div class="error-box">Não foi possível iniciar o aplicativo.</div>')});



